.eth-interact-btn {
  position: fixed;
  bottom: 48px;
  right: 40px;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.15);
  border: 2px solid rgba(255, 255, 255, 0.5);
  color: #fff;
  font-family: monospace;
  font-size: 18px;
  font-weight: bold;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 20;
  pointer-events: auto;
  animation: eth-pop 0.15s ease-out;
  -webkit-tap-highlight-color: transparent;
}

.eth-interact-btn:active {
  background: rgba(255, 255, 255, 0.35);
  transform: scale(0.92);
}

.eth-run-btn {
  position: fixed;
  bottom: 120px;
  right: 40px;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: rgba(255, 200, 80, 0.15);
  border: 2px solid rgba(255, 200, 80, 0.5);
  color: rgba(255, 200, 80, 0.9);
  font-family: monospace;
  font-size: 11px;
  font-weight: bold;
  letter-spacing: 0.5px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 20;
  pointer-events: auto;
  -webkit-tap-highlight-color: transparent;
  transition: background 0.08s, transform 0.08s;
  user-select: none;
  -webkit-user-select: none;
}

.eth-run-btn.active {
  background: rgba(255, 200, 80, 0.38);
  border-color: rgba(255, 220, 120, 0.9);
  color: #fff;
  transform: scale(0.94);
}

@keyframes eth-pop {
  from { transform: scale(0.5); opacity: 0; }
  to   { transform: scale(1);   opacity: 1; }
}

.eth-dialogue {
  position: fixed;
  bottom: 80px;
  left: 50%;
  transform: translateX(-50%);
  width: min(480px, 90vw);
  background: rgba(10, 10, 20, 0.92);
  border: 2px solid rgba(255, 255, 255, 0.25);
  border-radius: 8px;
  padding: 16px 20px;
  z-index: 30;
  pointer-events: auto;
  animation: eth-slide-up 0.18s ease-out;
}

@keyframes eth-slide-up {
  from { transform: translateX(-50%) translateY(16px); opacity: 0; }
  to   { transform: translateX(-50%) translateY(0);    opacity: 1; }
}

.eth-dialogue-name {
  color: #a8d8a8;
  font-family: monospace;
  font-size: 11px;
  font-weight: bold;
  letter-spacing: 1px;
  text-transform: uppercase;
  margin-bottom: 6px;
}

.eth-dialogue-text {
  color: #eee;
  font-family: monospace;
  font-size: 13px;
  line-height: 1.6;
}

.eth-dialogue-close {
  position: absolute;
  top: 8px;
  right: 10px;
  background: none;
  border: none;
  color: rgba(255,255,255,0.4);
  font-size: 16px;
  cursor: pointer;
  font-family: monospace;
  padding: 2px 6px;
  -webkit-tap-highlight-color: transparent;
}

.eth-dialogue-close:active {
  color: #fff;
}

