      </view>
      <view className="items-end" style={{ gap: 4 }}>
        <text className="text-[13px] font-bold text-gray-900">{formatPeso(netPay)}</text>
        <view className={`rounded-md px-1.5 py-0.5 ${jo.disbursement_type === 'ATM' ? 'bg-blue-100' : 'bg-amber-100'}`}>
