.kr-root *, .kr-root *::before, .kr-root *::after { box-sizing: border-box; }
.kr-root :focus-visible { outline: 2px solid var(--ink); outline-offset: -2px; }
.kr-win {
  height: calc(100dvh - 40px);
  min-height: 560px;
  display: grid;
