    "ticket_number": fmt.Sprintf("%s-%03d", queue.Prefix, lastPosition+1),
    "customer_name": customerName,
    "status": "waiting",
    "position": lastPosition + 1,
})
if err != nil {
    return response.Error(500, "Could not create ticket")
}
