signature: scheduler-test:cleanup-temp
description: Deletes temporary files older than 24h
schedule: '0 * * * *'
*/
public function handle(): int
{
    $start = microtime(true);
    $this->info('[Arkzen:scheduler-test] Running cleanup-temp...');

